  "The model writes the program and its tests, the phone runs them, and any error goes straight back to the model to fix — until the tests pass. Offline, in a locked sandbox.": "মডেল প্রোগ্রাম আর তার টেস্ট লেখে, ফোন সেগুলো চালায়, আর কোনো ভুল হলে সরাসরি মডেলের কাছে ঠিক করতে ফেরত যায় — যতক্ষণ না টেস্ট পাস করে। অফলাইনে, একটা বন্ধ স্যান্ডবক্সে।",
