  "Core Max, Sense, Zenith, Apex and Everest run on a computer: get them in the Attune desktop app.": "Core Max, Sense, Zenith, Apex আর Everest কম্পিউটারে চলে: Attune ডেস্কটপ অ্যাপে পাবেন।",
  "Too heavy for a phone — it can close the app. Core or Blaze run smoothly here; this one is in the desktop app.": "ফোনের জন্য খুব ভারী — অ্যাপ বন্ধ হয়ে যেতে পারে। এখানে Core বা Blaze মসৃণভাবে চলে; এটা ডেস্কটপ অ্যাপে আছে।",
