  "This model is large for this phone. It works, but answers come slowly and the phone gets warm. For quick, smooth answers use Qwen 3.5 4B — same Arabic, reads photos, about 3× faster.": "এই মডেলটি এই ফোনের জন্য বড়। চলবে, কিন্তু উত্তর ধীরে আসবে আর ফোন গরম হবে। দ্রুত, মসৃণ উত্তরের জন্য Qwen 3.5 4B ব্যবহার করুন — একই আরবি, ছবি পড়ে, প্রায় ৩ গুণ দ্রুত।",
