  "Any GGUF on Hugging Face as": "Hugging Face-এর যেকোনো GGUF, এভাবে",
  ", or a direct https link. Specialist and fine-tuned models install the same way — the photo reader is fetched too when the repo has one.": ", অথবা সরাসরি https লিংক। বিশেষায়িত ও ফাইন-টিউন করা মডেলও একইভাবে ইনস্টল হয় — রিপোতে ছবি পড়ার অংশ থাকলে সেটাও নামানো হয়।",
  "How it answers": "কীভাবে উত্তর দেবে",
  "e.g. I run a small shop in Egypt. Answer in Egyptian Arabic unless I write in English. Give prices in EGP.": "যেমন আমি মিসরে একটি ছোট দোকান চালাই। আমি ইংরেজিতে না লিখলে মিসরীয় আরবিতে উত্তর দিন। দাম EGP-তে দিন।",
  "Saved when you tap outside the box. Stays on this phone.": "বক্সের বাইরে ট্যাপ করলে সেভ হয়। এই ফোনেই থাকে।",
