  "Notifications are off for Attune — tap to allow them, or reminders can't appear.": "Attune-এর নোটিফিকেশন বন্ধ — চালু করতে ট্যাপ করুন, নইলে রিমাইন্ডার দেখা যাবে না।",
  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "রিমাইন্ডার ১০ মিনিট পর্যন্ত দেরিতে আসতে পারে। ঠিক সময়ে বাজাতে Attune-কে “অ্যালার্ম ও রিমাইন্ডার” অনুমতি দিতে ট্যাপ করুন।",
  "In the browser reminders are only listed — the Android app rings them.": "ব্রাউজারে রিমাইন্ডার শুধু তালিকায় দেখা যায় — Android অ্যাপ সেগুলো বাজায়।",
