  "No app on this phone can do that.": "এই ফোনের কোনো অ্যাপ সেটা করতে পারে না।",
  "WhatsApp isn't installed — opened the share sheet instead.": "WhatsApp ইনস্টল করা নেই — শেয়ার শিট খুলেছে।",
  "Unknown action": "অজানা অ্যাকশন",
