  "This build has no GPU engine — it will come with the next APK built on GitHub.": "এই বিল্ডে GPU ইঞ্জিন নেই — GitHub-এ তৈরি পরের APK-তে আসবে।",
  "MTP did not start on this phone, so this model runs without it.": "এই ফোনে MTP চালু হয়নি, তাই এই মডেল সেটা ছাড়াই চলছে।",
  "MTP is off for this model.": "এই মডেলের জন্য MTP বন্ধ।",
  "This model has no MTP layers; install it again from the list to get them.": "এই মডেলে MTP লেয়ার নেই; পেতে তালিকা থেকে আবার ইনস্টল করুন।",
  "Not recommended: it was slower in our tests. Turn it off.": "প্রস্তাবিত নয়: আমাদের পরীক্ষায় এটি ধীর ছিল। বন্ধ করুন।",
  "Faster answers with a draft model": "ড্রাফট মডেল দিয়ে দ্রুততর উত্তর",
  "On: {d} guesses ahead, the main model checks.": "চালু: {d}টি আন্দাজ এগিয়ে, মূল মডেল যাচাই করে।",
  "Qwen 3.5 0.8B guesses a few words ahead and the main model checks them in one go. Same answers, often faster writing.": "Qwen 3.5 0.8B কয়েক শব্দ এগিয়ে আন্দাজ করে আর মূল মডেল একবারে যাচাই করে। একই উত্তর, লেখা প্রায়ই দ্রুত।",
  "Only works with a Qwen 3.5 model — the one in use is not.": "শুধু Qwen 3.5 মডেলে কাজ করে — ব্যবহৃত মডেলটি তা নয়।",
  "Download Qwen 3.5 0.8B as a helper (about 0.5 GB, once). Works with Qwen 3.5 models.": "Qwen 3.5 0.8B সহায়ক হিসেবে ডাউনলোড করুন (প্রায় ০.৫ GB, একবার)। Qwen 3.5 মডেলে কাজ করে।",
  "Downloading the draft model…": "ড্রাফট মডেল ডাউনলোড হচ্ছে…",
