  "Stuck — starting again from scratch with a different approach": "আটকে গেছে — আলাদা পদ্ধতিতে একেবারে নতুন করে শুরু হচ্ছে",
  "Wrote it, with {n} tests.": "{n}টি টেস্টসহ লেখা হয়েছে।",
