  "✓ Ran without errors.": "✓ ত্রুটি ছাড়া চলেছে।",
  "The fix did not match the code.": "সংশোধনটি কোডের সঙ্গে মেলেনি।",
  "The model answered without code.": "মডেল কোড ছাড়া উত্তর দিয়েছে।",
  "The fix deleted the tests — refused.": "সংশোধনে টেস্ট মুছে গিয়েছিল — গ্রহণ করা হয়নি।",
  "The model answered without any code — try asking again in other words.": "মডেল কোড ছাড়াই উত্তর দিয়েছে — অন্য ভাষায় আবার জিজ্ঞেস করে দেখুন।",
  "A picture — Studio draws it on this phone": "একটি ছবি — স্টুডিও এই ফোনে আঁকে",
