  "Studio works in the Android app.": "স্টুডিও Android অ্যাপে কাজ করে।",
  "The chat model was paused to make room, and is loading again.": "জায়গা করে দিতে চ্যাট মডেল থামানো হয়েছিল, এখন আবার লোড হচ্ছে।",
  "This APK has no picture engine yet — it comes with the next APK built on GitHub.": "এই APK-তে এখনো ছবির ইঞ্জিন নেই — GitHub-এ তৈরি পরের APK-তে আসবে।",
  "This build draws on the CPU.": "এই বিল্ড CPU-তে আঁকে।",
  "This build of the app has no picture engine yet.": "অ্যাপের এই বিল্ডে এখনো ছবির ইঞ্জিন নেই।",
  "This phone has {n} GB — it may be too little for pictures.": "এই ফোনে {n} GB আছে — ছবির জন্য কম হতে পারে।",
  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "Attune-এর এই ভার্সনে গ্রাফিক্স চিপের ছবির ইঞ্জিন নেই, তাই ছবি CPU-তে আঁকা হয় (ধীর)। আপডেটে এটি যোগ হবে।",
  "The picture engine stopped responding while loading the model, so it was stopped. Engine → Engine log shows its last lines — send them to support.": "মডেল লোড করার সময় ছবির ইঞ্জিন সাড়া দেয়নি, তাই থামানো হয়েছে। ইঞ্জিন → ইঞ্জিন লগে এর শেষ লাইনগুলো দেখুন — সাপোর্টে পাঠান।",
  "This phone's GPU driver did not answer, so pictures are drawn on the CPU (slower).": "এই ফোনের GPU ড্রাইভার সাড়া দেয়নি, তাই ছবি CPU-তে আঁকা হচ্ছে (ধীর)।",
  "What should change? e.g. “make it night, with the street lights on”": "কী বদলাবে? যেমন “রাত করে দাও, রাস্তার বাতি জ্বালিয়ে”",
  "Write a fuller description first (better pictures; uses the chat model)": "আগে আরও পূর্ণ বর্ণনা লিখুন (ছবি ভালো হয়; চ্যাট মডেল ব্যবহার করে)",
  "Writing a fuller description…": "আরও পূর্ণ বর্ণনা লেখা হচ্ছে…",
