  "I couldn't make every test pass yet — here is the closest version; tap “Test & fix in Code” to keep going.": "এখনো সব টেস্ট পাস করাতে পারিনি — এটা সবচেয়ে কাছের ভার্সন; চালিয়ে যেতে “কোডে পরীক্ষা ও ঠিক করুন” ট্যাপ করুন।",
  "Working it out as a program…": "প্রোগ্রাম হিসেবে হিসাব করা হচ্ছে…",
  "Fixing the program and running it again…": "প্রোগ্রাম ঠিক করে আবার চালানো হচ্ছে…",
  "Checked by running code — writing the answer…": "কোড চালিয়ে যাচাই করা — উত্তর লেখা হচ্ছে…",
