  "Running it on your file…": "আপনার ফাইলে চালানো হচ্ছে…",
  "Computed from your file — writing the answer…": "আপনার ফাইল থেকে হিসাব হয়েছে — উত্তর লেখা হচ্ছে…",
  "Python is not in this build, so the file can't be computed on.": "এই বিল্ডে Python নেই, তাই ফাইলে হিসাব করা যায় না।",
  "What should it have said? Attune double-checks your correction first, and learns it only if it holds up.": "কী বলা উচিত ছিল? Attune আগে আপনার সংশোধন দুবার যাচাই করে, আর টিকলে তবেই শেখে।",
