  "e.g. unpaid invoices over 50,000 · jobs this month by customer · top 5 cranes by revenue": "যেমন ৫০,০০০-এর বেশি অপরিশোধিত ইনভয়েস · গ্রাহক অনুযায়ী এই মাসের কাজ · আয়ে সেরা ৫টি ক্রেন",
  "Load a model to ask your data in words.": "কথায় ডেটাকে প্রশ্ন করতে একটি মডেল লোড করুন।",
  "Query saved": "কোয়েরি সেভ হয়েছে",
  "Save query": "কোয়েরি সেভ করুন",
  "Saved queries": "সেভ করা কোয়েরি",
  "Describe a form — the fields to fill, in order": "একটি ফর্ম বর্ণনা করুন — কোন ফিল্ড পূরণ হবে, কোন ক্রমে",
  "e.g. a quick job form for the site: customer, crane, start date, days — status New": "যেমন সাইটের জন্য দ্রুত কাজের ফর্ম: গ্রাহক, ক্রেন, শুরুর তারিখ, দিন — স্ট্যাটাস নতুন",
  "Make the form": "ফর্ম বানান",
  "Load a model to make forms in words.": "কথায় ফর্ম বানাতে একটি মডেল লোড করুন।",
  "Form saved — pick it above the records when you add one": "ফর্ম সেভ হয়েছে — রেকর্ড যোগ করার সময় রেকর্ডের ওপরে এটি বেছে নিন",
  "Save form": "ফর্ম সেভ করুন",
  "No forms yet. A form shows only the fields you need, in your order, with ready values — pick it when you add a record.": "এখনও কোনো ফর্ম নেই। ফর্ম শুধু দরকারি ফিল্ডগুলো দেখায়, আপনার ক্রমে, তৈরি মানসহ — রেকর্ড যোগ করার সময় এটি বেছে নিন।",
  "Pasted from {t}": "{t} থেকে পেস্ট করা",
  "Copy & open {t}": "কপি করে {t} খুলুন",
  "Queries": "কোয়েরি",
  "Forms": "ফর্ম",
  "Open an app file (made with Attune)": "একটি অ্যাপ ফাইল খুলুন (Attune দিয়ে বানানো)",
  "That file isn't an app made with Attune Business.": "এই ফাইলটি Attune Business দিয়ে বানানো অ্যাপ নয়।",
  "Updated from the app file — {n} tables with their records": "অ্যাপ ফাইল থেকে আপডেট হয়েছে — রেকর্ডসহ {n}টি টেবিল",
  "Opened — {n} tables with their records": "খোলা হয়েছে — রেকর্ডসহ {n}টি টেবিল",
  "Change the design in words — add fields to any table, new tables, links…": "কথায় ডিজাইন বদলান — যেকোনো টেবিলে ফিল্ড, নতুন টেবিল, লিংক যোগ করুন…",
  "e.g. add Email and Tax ID to Suppliers, and a Warranty months field to Parts": "যেমন Suppliers-এ Email ও Tax ID, আর Parts-এ ওয়ারেন্টির মাস ফিল্ড যোগ করুন",
  "Saved — send this file; it opens in any browser, no Attune needed": "সেভ হয়েছে — এই ফাইলটি পাঠান; যেকোনো ব্রাউজারে খোলে, Attune লাগে না",
  "Excel files need Python, which isn't in this build — use CSV.": "Excel ফাইলের জন্য Python লাগে, যা এই বিল্ডে নেই — CSV ব্যবহার করুন।",
  "Making the Excel file…": "Excel ফাইল তৈরি হচ্ছে…",
  "Couldn't make the Excel file: {e}": "Excel ফাইল তৈরি করা যায়নি: {e}",
  "Give it to your team as an app: one file with all the data inside — it opens in any phone or computer browser, no Attune needed. When something needs changing, open the file here (Business → Open an app file), ask the AI, and send the new app back.": "আপনার টিমকে এটি অ্যাপ হিসেবে দিন: সব ডেটাসহ একটি ফাইল — যেকোনো ফোন বা কম্পিউটারের ব্রাউজারে খোলে, Attune লাগে না। কিছু বদলাতে হলে ফাইলটি এখানে খুলুন (ব্যবসা → অ্যাপ ফাইল খুলুন), AI-কে বলুন, আর নতুন অ্যাপটি ফেরত পাঠান।",
  "Export as an app": "অ্যাপ হিসেবে এক্সপোর্ট করুন",
  "Excel workbook (all tables)": "Excel ওয়ার্কবুক (সব টেবিল)",
  "The picture engine stopped before the picture was finished — Android may have closed it to free memory. Try “Quick draft”, or close other apps and try again.": "ছবি শেষ হওয়ার আগেই ছবির ইঞ্জিন থেমে গেছে — মেমরি খালি করতে Android হয়তো এটি বন্ধ করেছে। “দ্রুত খসড়া” চেষ্টা করুন, বা অন্য অ্যাপ বন্ধ করে আবার চেষ্টা করুন।",
  "The picture could not be made. Open Engine → Engine log and send me what it says.": "ছবিটি তৈরি করা যায়নি। ইঞ্জিন → ইঞ্জিন লগ খুলে সেখানে যা লেখা আছে আমাকে পাঠান।",
  "Multi-token prediction (faster writing)": "মাল্টি-টোকেন প্রেডিকশন (দ্রুত লেখা)",
  "Off by default: on some phones it doubles words and digits (“ItIt is is”, “20205”). Turn it on only if answers stay correct.": "ডিফল্টে বন্ধ: কিছু ফোনে এটি শব্দ ও অঙ্ক দ্বিগুণ করে (“ItIt is is”, “20205”)। উত্তর ঠিক থাকলে তবেই চালু করুন।",
  "The last picture didn't finish:": "শেষ ছবিটি শেষ হয়নি:",
  "Connected {n} fields to their tables": "{n}টি ফিল্ড তাদের টেবিলের সাথে যুক্ত হয়েছে",
  "Connect the tables for me ({n})": "আমার হয়ে টেবিলগুলো যুক্ত করুন ({n})",
  "Connected {n} fields — Undo (top) puts them back": "{n}টি ফিল্ড যুক্ত হয়েছে — ওপরের আনডু আগের মতো করে দেবে",
  "Connect the tables": "টেবিলগুলো যুক্ত করুন",
  "Something went wrong on this screen.": "এই স্ক্রিনে কিছু একটা ভুল হয়েছে।",
  "Your chats and data are safe. Try again — if it keeps happening, send me this message.": "আপনার চ্যাট ও ডেটা নিরাপদ। আবার চেষ্টা করুন — বারবার হলে এই মেসেজটি আমাকে পাঠান।",
  "Try again": "আবার চেষ্টা করুন",
  "Reading page {i} of {n} — {t}": "পৃষ্ঠা {i} / {n} পড়া হচ্ছে — {t}",
  "Checking what is still missing…": "এখনও কী বাকি আছে দেখা হচ্ছে…",
