  "Searching again for: {what}…": "আবার খোঁজা হচ্ছে: {what}…",
  "Writing the full answer from {n} pages…": "{n}টি পৃষ্ঠা থেকে পূর্ণ উত্তর লেখা হচ্ছে…",
  "read {p} pages one by one, facts from {n}": "{p}টি পৃষ্ঠা একে একে পড়া হয়েছে, {n}টি থেকে তথ্য",
  "Checking the picture engine and model files…": "ছবির ইঞ্জিন ও মডেল ফাইল চেক করা হচ্ছে…",
