  "Basic": "বেসিক",
  "Quick tidy-ups, short answers": "দ্রুত গুছিয়ে নেওয়া, ছোট উত্তর",
  "Planning the research…": "গবেষণার পরিকল্পনা করা হচ্ছে…",
  "Searching: {q}": "খোঁজা হচ্ছে: {q}",
  "{s} searches": "{s}টি সার্চ",
  "{c} facts confirmed by 2+ sites": "{c}টি তথ্য ২+ সাইটে নিশ্চিত",
  "Reviewing the answer like a senior expert…": "অভিজ্ঞ বিশেষজ্ঞের মতো উত্তরটি রিভিউ করা হচ্ছে…",
  "Reviewed by an expert pass": "বিশেষজ্ঞ রিভিউ করা হয়েছে",
  "Reviewed by an expert pass · {n} improvements": "বিশেষজ্ঞ রিভিউ করা হয়েছে · {n}টি উন্নতি",
  "Web search · {p} pages": "ওয়েব সার্চ · {p}টি পৃষ্ঠা",
  "Reads photos": "ছবি পড়ে",
  "Long message — reading it in parts ({i} of {n})…": "লম্বা মেসেজ — ভাগে ভাগে পড়া হচ্ছে ({i} / {n})…",
  "Something went wrong — trying again…": "কিছু একটা ভুল হয়েছে — আবার চেষ্টা করা হচ্ছে…",
  "Long answer — still writing ({n})…": "লম্বা উত্তর — এখনও লেখা হচ্ছে ({n})…",
  "Writing it out in words…": "কথায় লেখা হচ্ছে…",
  "Studio Turbo": "স্টুডিও Turbo",
  "Studio Pro": "স্টুডিও Pro",
  "Studio Pro HD": "স্টুডিও Pro HD",
  "Turbo · about 1 min": "Turbo · প্রায় ১ মিনিট",
  "Studio Turbo+": "স্টুডিও Turbo+",
  "Recommended for your phone": "আপনার ফোনের জন্য প্রস্তাবিত",
  "Studio Ultra": "স্টুডিও Ultra",
  "Ultra · best quality, slow · {s} GB": "Ultra · সেরা মান, ধীর · {s} GB",
  "best quality, slow": "সেরা মান, ধীর",
  "fastest pictures": "সবচেয়ে দ্রুত ছবি",
  "a graphics card with 8 GB or more: the most capable model": "8 GB বা বেশি গ্রাফিক্স কার্ড: সবচেয়ে সক্ষম মডেল",
  "The most capable model: text inside pictures, busy scenes, people. Slow on a phone (about 10 minutes a picture), fast on a computer with a graphics card. Needs 12 GB RAM.": "সবচেয়ে সক্ষম মডেল: ছবির ভেতরে লেখা, ভিড়ের দৃশ্য, মানুষ। ফোনে ধীর (প্রতি ছবিতে প্রায় ১০ মিনিট), গ্রাফিক্স কার্ডওয়ালা কম্পিউটারে দ্রুত। 12 GB RAM লাগে।",
  "about {s} s a picture": "প্রতি ছবিতে প্রায় {s} সেকেন্ড",
  "8 GB or more and fast cores: the sharper XL model in one step": "8 GB বা বেশি আর দ্রুত কোর: আরও স্পষ্ট XL মডেল এক ধাপে",
  "not enough free storage or speed for the XL model": "XL মডেলের জন্য যথেষ্ট খালি স্টোরেজ বা গতি নেই",
  "the fast model fits this phone's memory": "দ্রুত মডেলটি এই ফোনের মেমরিতে আঁটে",
  "little memory or slow cores: smaller pictures, still clear": "কম মেমরি বা ধীর কোর: ছোট ছবি, তবুও স্পষ্ট",
  "Turbo+ · about 20 s · {s} GB": "Turbo+ · প্রায় ২০ সেকেন্ড · {s} GB",
  "Faster and sharper than Turbo, with a better match to what you ask for: about 20 seconds a picture on the CPU. 512 px. For phones with 8 GB RAM or more.": "Turbo-র চেয়ে দ্রুত ও স্পষ্ট, আর আপনি যা চান তার সাথে বেশি মেলে: CPU-তে প্রতি ছবিতে প্রায় ২০ সেকেন্ড। 512 px। 8 GB বা বেশি RAM-এর ফোনের জন্য।",
  "Pro · best quality": "Pro · সেরা মান",
  "Pro on this phone's CPU: 10–20 min a picture": "এই ফোনের CPU-তে Pro: প্রতি ছবিতে ১০–২০ মিনিট",
  "This phone's graphics chip isn't working with Studio, so the Pro model would take 10–20 minutes a picture on the CPU. Studio Turbo makes a picture in about a minute.": "এই ফোনের গ্রাফিক্স চিপ স্টুডিওর সাথে কাজ করছে না, তাই CPU-তে Pro মডেলে প্রতি ছবিতে ১০–২০ মিনিট লাগবে। স্টুডিও Turbo প্রায় এক মিনিটে ছবি বানায়।",
  "Fast pictures on any phone: about a minute without a graphics chip, seconds with one. 512 px — great for ideas, drafts and posts.": "যেকোনো ফোনে দ্রুত ছবি: গ্রাফিক্স চিপ ছাড়া প্রায় এক মিনিট, থাকলে কয়েক সেকেন্ড। 512 px — আইডিয়া, খসড়া ও পোস্টের জন্য দারুণ।",
  "The best photo quality: people, places, products and text in pictures, 1024 px. Also edits a photo you give it (“make it night”, “remove the car”). Needs a working graphics chip — on the CPU a picture takes 10–20 minutes.": "সেরা ছবির মান: মানুষ, জায়গা, পণ্য ও ছবির ভেতরের লেখা, 1024 px। আপনার দেওয়া ছবিও এডিট করে (“রাত বানাও”, “গাড়িটা সরাও”)। চালু গ্রাফিক্স চিপ লাগে — CPU-তে প্রতি ছবিতে ১০–২০ মিনিট।",
  "Studio Pro at full precision: finer detail, cleaner faces, hands and text. Also edits your photos by instruction. Needs a working graphics chip and 12 GB RAM.": "পূর্ণ নির্ভুলতায় স্টুডিও Pro: আরও সূক্ষ্ম ডিটেইল, পরিষ্কার মুখ, হাত ও লেখা। নির্দেশ দিয়ে আপনার ছবিও এডিট করে। চালু গ্রাফিক্স চিপ ও 12 GB RAM লাগে।",
  "Still working — nothing is stuck. Turbo takes about 1–2 minutes on the CPU. Keep Attune open; Stop cancels it.": "এখনও কাজ চলছে — কিছু আটকে নেই। CPU-তে Turbo প্রায় ১–২ মিনিট নেয়। Attune খোলা রাখুন; থামান চাপলে বাতিল হবে।",
  "Still working — nothing is stuck. Without the graphics chip a Pro picture takes 10–20 minutes (edits take longer). For speed, pick Turbo. Keep Attune open; Stop cancels it.": "এখনও কাজ চলছে — কিছু আটকে নেই। গ্রাফিক্স চিপ ছাড়া একটি Pro ছবিতে ১০–২০ মিনিট লাগে (এডিটে আরও বেশি)। গতির জন্য Turbo বেছে নিন। Attune খোলা রাখুন; থামান চাপলে বাতিল হবে।",
  "Delete this chat?": "এই চ্যাট মুছবেন?",
  "This can't be undone.": "এটি আর ফেরানো যাবে না।",
