  "Remove this from the project?": "এটি প্রজেক্ট থেকে সরাবেন?",
  "Delete this picture?": "এই ছবি মুছবেন?",
  "Delete this place?": "এই জায়গা মুছবেন?",
  "Forget this correction?": "এই সংশোধন ভুলে যাবেন?",
