  "Spark (helper)": "Spark (সহকারী)",
  "Only works with Spark, Glow, Core and Zenith — not with the model in use.": "শুধু Spark, Glow, Core ও Zenith-এর সাথে কাজ করে — চালু মডেলের সাথে নয়।",
  "Download Spark as a helper (about 0.5 GB, once). Works with Glow, Core and Zenith.": "সহকারী হিসেবে Spark ডাউনলোড করুন (প্রায় 0.5 GB, একবারই)। Glow, Core ও Zenith-এর সাথে কাজ করে।",
  "This is a big model for a phone — Core is about 2–3× faster.": "ফোনের জন্য এটা বড় মডেল — Core প্রায় ২–৩ গুণ দ্রুত।",
  "The strongest model a 12 GB phone can run: expert answers, and the best at reading documents and photos.": "12 GB ফোনে চলা সবচেয়ে শক্তিশালী মডেল: বিশেষজ্ঞের মতো উত্তর, আর ডকুমেন্ট ও ছবি পড়ায় সেরা।",
  "Core made 10% smaller for a 4 GB phone — worth it over Glow.": "4 GB ফোনের জন্য 10% ছোট করা Core — Glow-এর চেয়ে ভালো।",
  "Runs on a budget phone and still reads photos. Good short answers; long reasoning shows its size.": "কম দামের ফোনেও চলে আর ছবি পড়ে। ছোট উত্তরে ভালো; লম্বা যুক্তিতে এর আকার বোঝা যায়।",
  "For a phone that can't hold anything else: tidying and shortening text. Not for reasoning.": "যে ফোনে আর কিছু ধরে না তার জন্য: লেখা গোছানো ও ছোট করা। যুক্তির কাজের জন্য নয়।",
  "The biggest speed-up on this phone is the fast engine: Blaze on the graphics chip — first words in about a second. Tap “Switch to the fast engine” above.": "এই ফোনে সবচেয়ে বড় গতি বাড়ানো হলো দ্রুত ইঞ্জিন: গ্রাফিক্স চিপে Blaze — প্রথম শব্দ প্রায় এক সেকেন্ডে। ওপরে “দ্রুত ইঞ্জিনে যান” ট্যাপ করুন।",
