  "Your free Pro trial: {n} days left — everything is unlocked. Keep it by choosing a plan.": "আপনার ফ্রি Pro ট্রায়াল: আর {n} দিন বাকি — সবকিছু খোলা। একটি প্ল্যান বেছে নিয়ে এটি রেখে দিন।",
