  "Data first, question last improves grounding": "আগে ডেটা, শেষে প্রশ্ন — উত্তর উৎসে বেশি ভিত্তি পায়",
  "Role-free outcome framing (2026 guidance)": "ভূমিকা ছাড়া ফলাফল-ভিত্তিক নির্দেশ (২০২৬ নির্দেশনা)",
  "Explicit output shape reduces rework": "স্পষ্ট আউটপুট গঠনে বারবার ঠিক করা কমে",
  "Goal + constraint framing produces usable scripts": "লক্ষ্য + শর্ত দিলে কাজে লাগার মতো স্ক্রিপ্ট হয়",
