  "PDF files are made by the Android app — open Attune on your phone.": "PDF ফাইল Android অ্যাপে তৈরি হয় — ফোনে Attune খুলুন।",
  "PDF files are read by the Android app — open Attune on your phone.": "PDF ফাইল Android অ্যাপে পড়া হয় — ফোনে Attune খুলুন।",
