  "Rewriting the slide…": "স্লাইড আবার লেখা হচ্ছে…",
  "Copy log": "লগ কপি করুন",
  "Send log": "লগ পাঠান",
  "Log copied — paste it in the chat": "লগ কপি হয়েছে — চ্যাটে পেস্ট করুন",
  "Couldn't copy — press and hold the log to select it": "কপি করা যায়নি — লগটি চেপে ধরে সিলেক্ট করুন",
  "Studio is drawing on the processor (slow). This phone has a graphics chip — try it: pictures and ×4 sharpening are many times faster there.": "স্টুডিও প্রসেসরে আঁকছে (ধীর)। এই ফোনে গ্রাফিক্স চিপ আছে — চেষ্টা করে দেখুন: ছবি আর ×৪ শার্প করা সেখানে অনেক গুণ দ্রুত।",
  "The next picture uses the graphics chip": "পরের ছবি গ্রাফিক্স চিপ ব্যবহার করবে",
  "This picture was drawn on the CPU because the graphics chip didn't finish; the next picture tries the graphics chip again.": "গ্রাফিক্স চিপ শেষ করতে পারেনি বলে এই ছবিটি CPU-তে আঁকা হয়েছে; পরের ছবিতে আবার গ্রাফিক্স চিপ চেষ্টা করা হবে।",
  "Drawing on the GPU failed twice, so Attune switched Studio to the CPU. ": "GPU-তে আঁকা দুবার ব্যর্থ হয়েছে, তাই Attune স্টুডিওকে CPU-তে নিয়ে গেছে। ",
  "The GPU driver stalled twice while loading the picture model, so Attune switched Studio to the CPU (you can try the GPU again below).": "ছবির মডেল লোড করার সময় GPU ড্রাইভার দুবার আটকে গেছে, তাই Attune স্টুডিওকে CPU-তে নিয়ে গেছে (নিচে আবার GPU চেষ্টা করতে পারেন)।",
  "Show only the models worth using on this device": "শুধু এই ডিভাইসে ব্যবহারযোগ্য মডেলগুলো দেখান",
