  "Not in {to} yet: {x}": "এখনো {to}-তে নেই: {x}",
  "Link them": "এগুলো জুড়ুন",
  "Linked: {t} › {f} → {to}": "জোড়া হয়েছে: {t} › {f} → {to}",
  "{n} added to {to}": "{to}-তে {n}টি যোগ হয়েছে",
  "When a column in one table names records of another (a job's customer, an invoice's crane), the phone finds it here and links them — no relationships to draw by hand.": "যখন এক টেবিলের কোনো কলামে অন্য টেবিলের রেকর্ডের নাম থাকে (কাজের গ্রাহক, ইনভয়েসের ক্রেন), ফোন এখানে তা খুঁজে জুড়ে দেয় — হাতে সম্পর্ক আঁকতে হয় না।",
  "{t} with its linked tables": "{t} ও এর সাথে জোড়া টেবিল",
  "{n} records · with {l}": "{n}টি রেকর্ড · সাথে {l}",
