  "Without the graphics chip, the ×4 AI sharpen takes about {m} minutes on this phone. “×2 sharper” takes a second. Start the ×4?": "গ্রাফিক্স চিপ ছাড়া এই ফোনে ×৪ AI শার্প করতে প্রায় {m} মিনিট লাগে। “×২ বেশি স্পষ্ট” এক সেকেন্ডে হয়। ×৪ শুরু করবেন?",
  "Highest resolution — sharpen every picture (×4 with the graphics chip; an instant ×2 without it)": "সর্বোচ্চ রেজোলিউশন — প্রতিটি ছবি শার্প করুন (গ্রাফিক্স চিপে ×৪; না থাকলে তাৎক্ষণিক ×২)",
