  "From the phone's Notebook app: open a note (or select several) → Share → Attune → “Save to Shelf”. Or pick exported files here: text, Word, PDF, web pages, Google Keep, Evernote, a .zip, or photos of notes.": "ফোনের Notebook অ্যাপ থেকে: একটি নোট খুলুন (বা কয়েকটি সিলেক্ট করুন) → শেয়ার → Attune → “শেলফে সেভ করুন”। অথবা এক্সপোর্ট করা ফাইল এখানে বেছে নিন: টেক্সট, Word, PDF, ওয়েব পেজ, Google Keep, Evernote, একটি .zip, বা নোটের ছবি।",
