  "Nothing found for that — try the area's name too (e.g. “… New Cairo”), or move the map there and search again.": "কিছু পাওয়া যায়নি — এলাকার নামও লিখুন (যেমন “… New Cairo”), অথবা ম্যাপ সেখানে সরিয়ে আবার খুঁজুন।",
  "from the map's centre": "ম্যাপের মাঝখান থেকে",
  "saved place": "সেভ করা জায়গা",
  "Save this place": "এই জায়গা সেভ করুন",
