  "Location is off for Attune — allow it in the phone's settings to see where you are.": "Attune-এর জন্য লোকেশন বন্ধ — আপনি কোথায় আছেন দেখতে ফোনের সেটিংসে অনুমতি দিন।",
  "Couldn't get your location — check that location is on.": "আপনার লোকেশন পাওয়া যায়নি — লোকেশন চালু আছে কিনা দেখুন।",
  "“{n}” isn't kept on this phone any more — pick the file again.": "“{n}” আর এই ফোনে রাখা নেই — ফাইলটি আবার বেছে নিন।",
  "tap to continue": "চালিয়ে যেতে ট্যাপ করুন",
  "The text and your questions are kept on this phone only. Forget removes them.": "লেখা আর আপনার প্রশ্ন শুধু এই ফোনেই রাখা হয়। ভুলে যান চাপলে সেগুলো মুছে যায়।",
  "Web · Auto": "ওয়েব · অটো",
  "Web: Auto — it searches only when a question needs fresh facts": "ওয়েব: অটো — কোনো প্রশ্নে নতুন তথ্য লাগলে তবেই খোঁজে",
  "Pick the best model for each question": "প্রতিটি প্রশ্নের জন্য সেরা মডেল বেছে নিন",
  "Reading your {f} conversation…": "আপনার {f} কথোপকথন পড়া হচ্ছে…",
  "Reading the conversation…": "কথোপকথন পড়া হচ্ছে…",
  "Shared links are opened in the Android app — or paste the conversation's text here.": "শেয়ার করা লিংক Android অ্যাপে খোলে — অথবা কথোপকথনের লেখা এখানে পেস্ট করুন।",
  "I read your conversation with {f}{t} (about {n} words). Ask me anything about it — check it, summarise it, or carry on from where it stopped.": "আমি {f}{t}-এর সাথে আপনার কথোপকথন পড়েছি (প্রায় {n} শব্দ)। এ নিয়ে যা খুশি জিজ্ঞেস করুন — যাচাই, সারাংশ, বা যেখানে থেমেছিল সেখান থেকে চালিয়ে যাওয়া।",
  "Attune · the AI runs on your device · no account, no sign-in · web lookup only when a question needs it (Auto) — switch it off with the Web button": "Attune · AI আপনার ডিভাইসেই চলে · কোনো অ্যাকাউন্ট বা সাইন-ইন নেই · প্রশ্নে দরকার হলে তবেই ওয়েবে খোঁজে (অটো) — ওয়েব বাটন দিয়ে বন্ধ করুন",
  "Web: Off — nothing is looked up": "ওয়েব: বন্ধ — কিছুই খোঁজা হয় না",
  "While Web is off in Chat, questions about prices, specs, news, scores or this year are still looked up (only the search words leave the phone). Off: nothing is looked up unless you turn Web on.": "চ্যাটে ওয়েব বন্ধ থাকলেও দাম, স্পেসিফিকেশন, খবর, স্কোর বা এই বছর নিয়ে প্রশ্ন খোঁজা হয় (শুধু সার্চের শব্দগুলো ফোনের বাইরে যায়)। বন্ধ: আপনি ওয়েব চালু না করলে কিছুই খোঁজা হয় না।",
  "The model wrote nonsense — restarting it in safe mode and asking again…": "মডেল অর্থহীন লিখেছে — নিরাপদ মোডে আবার চালু করে আবার জিজ্ঞেস করা হচ্ছে…",
  "This model writes nonsense on this phone, even in safe mode. Pick another model in Engine (Core works well) and tell us which one failed.": "এই মডেল এই ফোনে নিরাপদ মোডেও অর্থহীন লেখে। ইঞ্জিনে অন্য মডেল বেছে নিন (Core ভালো কাজ করে) এবং কোনটি ব্যর্থ হয়েছে আমাদের জানান।",
  "Safe mode is on for this model: it once wrote nonsense on this phone, so it runs without speed tricks and with full-precision memory (a little slower, same answers).": "এই মডেলের জন্য নিরাপদ মোড চালু: এটি একবার এই ফোনে অর্থহীন লিখেছিল, তাই এটি গতি বাড়ানোর কৌশল ছাড়া এবং পূর্ণ-নির্ভুল মেমরিতে চলে (একটু ধীর, উত্তর একই)।",
  "Turn safe mode off": "নিরাপদ মোড বন্ধ করুন",
