  "Download a whole country once: every road, building, place and shop, and search — all with no signal. A new version is built every week from OpenStreetMap; the app tells you when one is ready.": "পুরো একটি দেশ একবার ডাউনলোড করুন: প্রতিটি রাস্তা, ভবন, জায়গা ও দোকান, আর সার্চ — সবই নেটওয়ার্ক ছাড়া। প্রতি সপ্তাহে OpenStreetMap থেকে নতুন ভার্সন তৈরি হয়; প্রস্তুত হলে অ্যাপ আপনাকে জানাবে।",
