  "With signal, every country here shows online without downloading — every street, compound and place. Download only to use it with no signal.": "নেটওয়ার্ক থাকলে এখানকার প্রতিটি দেশ ডাউনলোড ছাড়াই অনলাইনে দেখা যায় — প্রতিটি রাস্তা, কম্পাউন্ড ও জায়গা। শুধু নেটওয়ার্ক ছাড়া ব্যবহারের জন্য ডাউনলোড করুন।",
