  "Android does this for apps installed from a file instead of Google Play. In App info tap ⋮ (top right) → Allow restricted settings, then turn Attune on here again.": "Google Play-র বদলে ফাইল থেকে ইনস্টল করা অ্যাপে Android এমন করে। App info-তে ⋮ (ওপরে ডানে) → Allow restricted settings ট্যাপ করুন, তারপর এখানে আবার Attune চালু করুন।",
