  "Use the NPU (experimental)": "NPU ব্যবহার করুন (পরীক্ষামূলক)",
  "Running on the NPU ({d}).": "NPU-তে চলছে ({d})।",
  "Runs the model on the Snapdragon NPU (Hexagon): much cooler, often faster at reading. Works best with Core Max (8-bit). Switches itself back to the CPU if anything goes wrong.": "মডেলটি Snapdragon NPU (Hexagon)-তে চালায়: অনেক ঠান্ডা, পড়তে প্রায়ই দ্রুত। Core Max (8-bit)-এর সাথে সবচেয়ে ভালো চলে। কিছু ভুল হলে নিজেই CPU-তে ফিরে যায়।",
  "This phone's NPU could not be used by the engine — Attune stays on the CPU.": "এই ফোনের NPU ইঞ্জিন ব্যবহার করতে পারেনি — Attune CPU-তেই থাকবে।",
  "Last time, starting on the NPU closed the app. Attune is back on the CPU; you can try it again in Engine → Speed.": "গতবার NPU-তে চালু করায় অ্যাপ বন্ধ হয়ে গিয়েছিল। Attune আবার CPU-তে; ইঞ্জিন → গতি থেকে আবার চেষ্টা করতে পারেন।",
  "You have {b}. Until {d} ({n} days) these are due: {t}. What is left, shared over the days, is what you can spend each day.": "আপনার আছে {b}। {d} পর্যন্ত ({n} দিন) এগুলো দিতে হবে: {t}। যা বাকি থাকে, দিনগুলোতে ভাগ করলে, সেটাই প্রতিদিন খরচ করতে পারবেন।",
  "Nothing due before then.": "তার আগে কিছু দেওয়ার নেই।",
  "Tip: add your salary as a repeating income in Money, and this counts until payday.": "টিপ: টাকা-তে আপনার বেতন নিয়মিত আয় হিসেবে যোগ করুন, তাহলে এটি বেতনের দিন পর্যন্ত গুনবে।",
