  "Installments are cheaper in real money by {x}: keep the cash in the bank and pay monthly from it.": "প্রকৃত মূল্যে কিস্তি {x} সস্তা: নগদ টাকা ব্যাংকে রেখে সেখান থেকে মাসে মাসে দিন।",
  "Cash is cheaper in real money by {x}, even after what the bank would pay you.": "প্রকৃত মূল্যে নগদ {x} সস্তা, ব্যাংক যা দিত তা হিসাব করার পরও।",
  "Cash and installments cost about the same in real money.": "প্রকৃত মূল্যে নগদ আর কিস্তির খরচ প্রায় সমান।",
