  "Mission started — Attune works on it every day": "মিশন শুরু হয়েছে — Attune প্রতিদিন এতে কাজ করবে",
  "Say a goal with a deadline. Attune works on it every day: it reads your money, food and Scout ads, gives your real chance, and the one step for today.": "ডেডলাইনসহ একটি লক্ষ্য বলুন। Attune প্রতিদিন এতে কাজ করে: আপনার টাকা, খাবার আর স্কাউটের বিজ্ঞাপন দেখে, আপনার আসল সম্ভাবনা আর আজকের একটি ধাপ জানায়।",
  "e.g. «عايز أوفر 60 ألف قبل يونيو»": "যেমন «عايز أوفر 60 ألف قبل يونيو»",
