  "Lose {t} kg": "{t} kg কমান",
  "Buy it for {t} or less": "{t} বা তার কমে কিনুন",
  "by {d}": "{d}-এর মধ্যে",
  "add a date (e.g. by June)": "একটি তারিখ যোগ করুন (যেমন জুনের মধ্যে)",
  "Say a number and a date: save 60,000 by June · lose 6 kg before 20 January · buy … under 900k by 1 December · spend no more than 3,000 on food this month · pay off Ahmed's debt by December · finish the Turkish course by December.": "একটি সংখ্যা আর তারিখ বলুন: জুনের মধ্যে ৬০,০০০ সঞ্চয় · ২০ জানুয়ারির আগে ৬ kg কমানো · ১ ডিসেম্বরের মধ্যে ৯ লাখের নিচে … কেনা · এই মাসে খাবারে ৩,০০০-এর বেশি খরচ নয় · ডিসেম্বরের মধ্যে আহমেদের ঋণ শোধ · ডিসেম্বরের মধ্যে তুর্কি কোর্স শেষ।",
  "Start the mission": "মিশন শুরু করুন",
  "Your money missions need {a} a month together, but you keep about {b}. Pause one, or move a date.": "আপনার টাকার মিশনগুলোতে একসাথে মাসে {a} দরকার, কিন্তু আপনি রাখতে পারেন প্রায় {b}। একটি থামান, বা একটি তারিখ সরান।",
  "No missions yet. Start one above — a saving goal, a weight goal, something to buy, a spending limit, a debt or a course.": "এখনো কোনো মিশন নেই। ওপরে একটি শুরু করুন — সঞ্চয়ের লক্ষ্য, ওজনের লক্ষ্য, কিছু কেনা, খরচের সীমা, ঋণ বা একটি কোর্স।",
  "A goal with a date — Attune works on it every day": "তারিখসহ একটি লক্ষ্য — Attune প্রতিদিন এতে কাজ করে",
  "{c}% chance": "{c}% সম্ভাবনা",
  "A goal with a date — Attune works on it every day and shows your real chance": "তারিখসহ একটি লক্ষ্য — Attune প্রতিদিন এতে কাজ করে আর আপনার আসল সম্ভাবনা দেখায়",
  "Where": "কোথায়",
  "Every tool in three steps, with a drawing of its screen — and a plan to make Attune part of your day.": "প্রতিটি টুল তিন ধাপে, তার স্ক্রিনের ছবিসহ — আর Attune-কে আপনার দিনের অংশ করার একটি প্ল্যান।",
  "Sync": "সিঙ্ক",
  "Backup & sync": "ব্যাকআপ ও সিঙ্ক",
  "Synced — {a} new, {c} updated. Reopening…": "সিঙ্ক হয়েছে — {a}টি নতুন, {c}টি আপডেট। আবার খুলছে…",
  "Waiting for the other device…": "অন্য ডিভাইসের জন্য অপেক্ষা…",
  "Merging…": "মিলিয়ে নেওয়া হচ্ছে…",
  "Locking and sending…": "লক করে পাঠানো হচ্ছে…",
  "Signing in to Google…": "Google-এ সাইন ইন হচ্ছে…",
  "Locking and uploading…": "লক করে আপলোড হচ্ছে…",
  "Type the address shown on the other device, like 192.168.1.20:41873": "অন্য ডিভাইসে দেখানো ঠিকানাটি টাইপ করুন, যেমন 192.168.1.20:41873",
  "The code has 8 letters and numbers": "কোডে ৮টি অক্ষর ও সংখ্যা আছে",
  "Set your sync passphrase first — the same on every device.": "আগে আপনার সিঙ্ক পাসফ্রেজ সেট করুন — প্রতিটি ডিভাইসে একই।",
  "Keep your phone and computer (or two phones) the same. The data is locked before it leaves this device; what you delete on one is deleted on the other, nothing else is lost.": "আপনার ফোন আর কম্পিউটার (বা দুটি ফোন) একই রাখুন। ডেটা এই ডিভাইস ছাড়ার আগেই লক হয়; একটিতে যা মুছবেন তা অন্যটিতেও মুছে যাবে, আর কিছু হারাবে না।",
  "Wi-Fi": "Wi-Fi",
  "Google Drive": "Google Drive",
  "Allow Attune to find your other device on this Wi-Fi (Android asks once).": "এই Wi-Fi-তে Attune-কে আপনার অন্য ডিভাইস খুঁজতে দিন (Android একবার জিজ্ঞেস করে)।",
  "On the other device: Backup → Sync → Wi-Fi → Connect, and type:": "অন্য ডিভাইসে: ব্যাকআপ → সিঙ্ক → Wi-Fi → কানেক্ট, আর টাইপ করুন:",
  "not on Wi-Fi": "Wi-Fi-তে নেই",
  "Show a code on this device": "এই ডিভাইসে একটি কোড দেখান",
  "Or connect to the other device": "অথবা অন্য ডিভাইসে কানেক্ট করুন",
  "Make this device exactly like the other one (removes what the other doesn't have)": "এই ডিভাইসকে হুবহু অন্যটির মতো করুন (অন্যটিতে যা নেই তা সরিয়ে দেয়)",
  "Connect and sync": "কানেক্ট করে সিঙ্ক করুন",
  "One file in your own Google Drive, in a hidden folder only Attune can open. It is locked with your sync passphrase on this device, so Google only stores noise.": "আপনার নিজের Google Drive-এ একটি ফাইল, একটি লুকানো ফোল্ডারে যা শুধু Attune খুলতে পারে। এটি এই ডিভাইসেই আপনার সিঙ্ক পাসফ্রেজ দিয়ে লক করা, তাই Google শুধু অর্থহীন ডেটা রাখে।",
  "Sync passphrase set on this device.": "এই ডিভাইসে সিঙ্ক পাসফ্রেজ সেট হয়েছে।",
  "Sync passphrase (10+ characters, the same on every device)": "সিঙ্ক পাসফ্রেজ (১০+ অক্ষর, প্রতিটি ডিভাইসে একই)",
  "Save passphrase": "পাসফ্রেজ সেভ করুন",
