  "Wrong code or passphrase — nothing was changed.": "ভুল কোড বা পাসফ্রেজ — কিছুই বদলায়নি।",
  "Use at least 10 characters — the file lives in your Drive, so the passphrase is its only lock.": "অন্তত 10টি অক্ষর ব্যবহার করুন — ফাইলটি আপনার Drive-এ থাকে, তাই পাসফ্রেজই এর একমাত্র তালা।",
  "That passphrase is too easy to guess.": "এই পাসফ্রেজ অনুমান করা খুব সহজ।",
