  "The AI ran on this device: none of your chats, notes, photos or money went to an AI company.": "AI এই ডিভাইসেই চলেছে: আপনার কোনো চ্যাট, নোট, ছবি বা টাকা কোনো AI কোম্পানিতে যায়নি।",
