  "{who} owes you {amount} — remind them, or it gets forgotten.": "{who}-এর কাছে আপনার {amount} পাওনা — মনে করিয়ে দিন, নইলে ভুলে যাবে।",
  "You owe {who} {amount} — paying late costs trust.": "আপনার কাছে {who}-এর {amount} পাওনা — দেরিতে শোধ করলে বিশ্বাস কমে।",
