  "Weigh yourself 2–3 times a week for two weeks and your target will follow what your body really does.": "দুই সপ্তাহ ধরে সপ্তাহে 2–3 বার ওজন মাপুন, তাহলে আপনার লক্ষ্য আপনার শরীরের আসল হিসাব অনুসরণ করবে।",
  "You ate about {eaten} kcal a day and your weight held — so you burn about {burn}. Your plan now counts {tdee}.": "আপনি দিনে প্রায় {eaten} kcal খেয়েছেন আর ওজন একই ছিল — তাই আপনি প্রায় {burn} পোড়ান। আপনার প্ল্যান এখন {tdee} ধরে।",
  "You ate about {eaten} kcal a day and lost {kg} kg a week — so you burn about {burn}. Your plan now counts {tdee}.": "আপনি দিনে প্রায় {eaten} kcal খেয়েছেন আর সপ্তাহে {kg} kg কমেছে — তাই আপনি প্রায় {burn} পোড়ান। আপনার প্ল্যান এখন {tdee} ধরে।",
  "You ate about {eaten} kcal a day and gained {kg} kg a week — so you burn about {burn}. Your plan now counts {tdee}.": "আপনি দিনে প্রায় {eaten} kcal খেয়েছেন আর সপ্তাহে {kg} kg বেড়েছে — তাই আপনি প্রায় {burn} পোড়ান। আপনার প্ল্যান এখন {tdee} ধরে।",
