  "Don't do it": "এটা করবেন না",
  "Stress tests: chance cash never runs out": "স্ট্রেস টেস্ট: নগদ কখনো না ফুরানোর সম্ভাবনা",
  "Median of 2,000 futures in today's {c}, from your last {d} days in Money. Installments are fixed, so inflation makes them smaller each month; savings earn the certificate rate. A model, not a promise.": "আজকের {c}-এ 2,000টি ভবিষ্যতের মধ্যমা, টাকা-তে আপনার শেষ {d} দিন থেকে। কিস্তি নির্দিষ্ট, তাই মূল্যস্ফীতি প্রতি মাসে এগুলোকে ছোট করে; সঞ্চয়ে সার্টিফিকেটের হার পাওয়া যায়। এটি একটি মডেল, প্রতিশ্রুতি নয়।",
  "Careful: with every option, your cash runs out in more than 1 future in 10. The safest is {best} ({ok}% of futures stay above zero).": "সাবধান: প্রতিটি বিকল্পে 10টির মধ্যে 1টির বেশি ভবিষ্যতে আপনার নগদ ফুরিয়ে যায়। সবচেয়ে নিরাপদ {best} ({ok}% ভবিষ্যৎ শূন্যের উপরে থাকে)।",
  "{best}: {ok}% of futures never run out of cash; after 5 years you would have about {worth} (today's pounds, including what you bought).": "{best}: {ok}% ভবিষ্যতে নগদ কখনো ফুরায় না; 5 বছর পর আপনার প্রায় {worth} থাকবে (আজকের পাউন্ডে, কেনা জিনিসসহ)।",
  "{best} is better: {ok}% of futures never run out of cash, and after 5 years you would have about {worth} in today's pounds — {diff} more than {other}.": "{best} ভালো: {ok}% ভবিষ্যতে নগদ কখনো ফুরায় না, আর 5 বছর পর আজকের পাউন্ডে প্রায় {worth} থাকবে — {other}-এর চেয়ে {diff} বেশি।",
  "The answer came in English — writing it again in Arabic…": "উত্তর ইংরেজিতে এসেছে — আরবিতে আবার লিখছি…",
  "The answer came in the wrong language — writing it again in English…": "উত্তর ভুল ভাষায় এসেছে — ইংরেজিতে আবার লিখছি…",
  "{n} calculations checked by code — all correct": "{n}টি হিসাব কোড দিয়ে যাচাই — সব সঠিক",
  "Checked by code: {n} calculation(s) don't add up": "কোড দিয়ে যাচাই: {n}টি হিসাব মেলে না",
  "not": "না",
  "Copy all": "সব কপি করুন",
  "not published": "অপ্রকাশিত",
  "Message alerts": "মেসেজ সতর্কতা",
  "Tell Attune whose message you are waiting for — on WhatsApp, Gmail or any email app — and it tells you the moment it arrives. Checked on this phone; SMS only if you switch it on below.": "Attune-কে বলুন কার মেসেজের অপেক্ষা করছেন — WhatsApp, Gmail বা যেকোনো ইমেইল অ্যাপে — আর আসামাত্র জানাবে। এই ফোনেই যাচাই হয়; SMS শুধু নিচে চালু করলে।",
  "Turn on Notification access for Attune so it can see new messages (Settings opens). If it is grey, see “restricted setting” in Money → Payments.": "নতুন মেসেজ দেখতে Attune-এর জন্য নোটিফিকেশন অ্যাক্সেস চালু করুন (সেটিংস খুলবে)। ধূসর হলে টাকা → পেমেন্টে «সীমিত সেটিং» দেখুন।",
  "e.g. tell me when Ahmed messages me": "যেমন Ahmed মেসেজ দিলে আমাকে জানাও",
  "Say who, like: tell me when Ahmed messages me": "কে তা বলুন, যেমন: Ahmed মেসেজ দিলে আমাকে জানাও",
  "I'll tell you: {r}": "আমি জানাব: {r}",
  "Last alerts": "শেষ সতর্কতা",
