  "No tables found in this PDF.": "এই PDF-এ কোনো টেবিল পাওয়া যায়নি।",
  "Table {n}": "টেবিল {n}",
  "{n} tables saved to Excel": "{n}টি টেবিল Excel-এ সংরক্ষিত",
