  "Learned from your corrections": "আপনার সংশোধন থেকে শিখেছে",
  "Tap 👎 on an answer in a chat with this assistant and write the right one — it becomes a rule here.": "এই সহকারীর চ্যাটে কোনো উত্তরে 👎 চাপুন আর সঠিকটি লিখুন — এটি এখানে একটি নিয়ম হয়ে যায়।",
