  "The crane, radius and load come from the Lift tab. Add the rest and make the plan as a PDF to sign.": "ক্রেন, ব্যাসার্ধ ও লোড লিফট ট্যাব থেকে আসে। বাকিটা যোগ করে স্বাক্ষরের জন্য PDF প্ল্যান বানান।",
