  "GO — within every limit": "চলুন — সব সীমার মধ্যে",
  "GO WITH CARE — read the cautions": "সাবধানে চলুন — সতর্কতাগুলো পড়ুন",
  "CRITICAL LIFT — a signed lift plan is required": "গুরুত্বপূর্ণ লিফট — স্বাক্ষরিত লিফট প্ল্যান প্রয়োজন",
