  "INCOMPLETE — fill the missing checks": "অসম্পূর্ণ — বাকি চেকগুলো পূরণ করুন",
  "Load chart": "লোড চার্ট",
  "Ground under the outriggers": "আউটরিগারের নিচের মাটি",
