  "Backs up by itself every day": "প্রতিদিন নিজে ব্যাকআপ নেয়",
  "Back up by itself every day": "প্রতিদিন নিজে ব্যাকআপ নিন",
  "To {w}. Last: {t}. Everything, with Recall's messages, locked with your backup password; the newest 3 are kept.": "{w}-এ। শেষ: {t}। রিকলের মেসেজসহ সবকিছু, আপনার ব্যাকআপ পাসওয়ার্ডে লক; সর্বশেষ 3টি রাখা হয়।",
  "Like WhatsApp: pick a folder once — on this phone (offline) or in Google Drive (online) — and Attune saves a locked backup there every day, messages included.": "WhatsApp-এর মতো: একবার একটি ফোল্ডার বাছুন — এই ফোনে (অফলাইন) বা Google Drive-এ (অনলাইন) — আর Attune প্রতিদিন সেখানে লক করা ব্যাকআপ রাখে, মেসেজসহ।",
