  "Let Attune sort it": "Attune-কে সাজাতে দিন",
  "Couldn't read that file — pick the .xml the SMS backup app made.": "সেই ফাইল পড়া যায়নি — SMS ব্যাকআপ অ্যাপের বানানো .xml বাছুন।",
  "No bank or wallet messages from the last year in that file.": "সেই ফাইলে গত বছরের কোনো ব্যাংক বা ওয়ালেট মেসেজ নেই।",
  "From Google Play, install a free SMS backup app — e.g. “SMS Backup & Restore”.": "Google Play থেকে একটি ফ্রি SMS ব্যাকআপ অ্যাপ ইনস্টল করুন — যেমন «SMS Backup & Restore»।",
  "Open it → Back up → only Messages → save on this phone (Downloads).": "এটি খুলুন → ব্যাকআপ → শুধু মেসেজ → এই ফোনে সংরক্ষণ (ডাউনলোড)।",
