  "How?": "কীভাবে?",
  "Attune doesn't ask for SMS access (Google blocks apps installed from a file that do) — it reads the backup file instead.": "Attune SMS অ্যাক্সেস চায় না (Google ফাইল থেকে ইনস্টল হওয়া এমন অ্যাপ আটকায়) — বরং ব্যাকআপ ফাইল পড়ে।",
  "Nothing had all your words — the closest:": "কোনোটিতেই আপনার সব শব্দ ছিল না — সবচেয়ে কাছেরগুলো:",
  "Nothing to search yet — add screenshots or keep your notifications below": "এখনো খোঁজার কিছু নেই — স্ক্রিনশট যোগ করুন বা নিচে নোটিফিকেশন রাখুন",
  "Add screenshots and photos": "স্ক্রিনশট ও ছবি যোগ করুন",
  "Their text is read on the phone, so “the receipt from Carrefour” finds them. They are kept in Mind.": "এদের লেখা ফোনেই পড়া হয়, তাই «Carrefour-এর রসিদ» এগুলো খুঁজে পায়। এগুলো মাইন্ড-এ রাখা হয়।",
  "Keep my notifications for 30 days": "আমার নোটিফিকেশন 30 দিন রাখুন",
  "WhatsApp, SMS, email, deliveries, banks — so you can find what someone sent. Never one-time codes. Turning it off forgets them.": "WhatsApp, SMS, ইমেইল, ডেলিভারি, ব্যাংক — যাতে কে কী পাঠিয়েছে খুঁজে পান। কখনো ওয়ান-টাইম কোড নয়। বন্ধ করলে ভুলে যায়।",
  "Needs Notification access (the same switch as Money).": "নোটিফিকেশন অ্যাক্সেস লাগবে (টাকা-র মতো একই সুইচ)।",
