  "Your watch's temperature rose {r} °C: ovulation around {o}, so the period is expected {n}.": "আপনার ঘড়ির তাপমাত্রা {r} °C বেড়েছে: ডিম্বস্ফোটন প্রায় {o}, তাই পিরিয়ড {n} প্রত্যাশিত।",
