  "(14 days after ovulation until 2 cycles are measured)": "(2টি চক্র মাপা পর্যন্ত ডিম্বস্ফোটনের 14 দিন পর)",
  "No temperature rise yet — ovulation looks later than usual, so the period will likely be later than the date above.": "এখনো তাপমাত্রা বাড়েনি — ডিম্বস্ফোটন স্বাভাবিকের চেয়ে দেরিতে মনে হচ্ছে, তাই পিরিয়ড সম্ভবত উপরের তারিখের চেয়ে দেরিতে হবে।",
  "{n} nights of temperature from your watch — the rise after ovulation shows here.": "আপনার ঘড়ি থেকে {n} রাতের তাপমাত্রা — ডিম্বস্ফোটনের পরের বৃদ্ধি এখানে দেখায়।",
  "A watch that measures night temperature (Galaxy Watch, Pixel Watch, Oura…) makes the prediction more exact.": "রাতের তাপমাত্রা মাপা ঘড়ি (Galaxy Watch, Pixel Watch, Oura…) পূর্বাভাস আরও সঠিক করে।",
