  "I didn't get that as an automation. Try: When my salary arrives, put 20% in the car fund.": "এটি অটোমেশন হিসেবে বুঝিনি। চেষ্টা করুন: বেতন এলে 20% গাড়ির ফান্ডে রাখো।",
