  "It listens to your bank and wallet notifications (never SMS). When one matches, you get a notification at once and the money goes into the pot.": "এটি আপনার ব্যাংক ও ওয়ালেট নোটিফিকেশন শোনে (কখনো SMS নয়)। কোনোটি মিললে সাথে সাথে নোটিফিকেশন পান আর টাকা পাত্রে যায়।",
  "Turn on Notification access for Attune first": "আগে Attune-এর জন্য নোটিফিকেশন অ্যাক্সেস চালু করুন",
