  "Your details — bookings and better answers": "আপনার তথ্য — বুকিং ও ভালো উত্তর",
  "Private: everything here stays on this phone — Attune never uploads it, and its AI runs on the phone. Answers and agents use only your trip and daily-life details (never your passport, phone or email). A booking site gets your name, passport and phone only when you tap “Fill my details”.": "গোপন: এখানকার সবকিছু এই ফোনে থাকে — Attune কখনো আপলোড করে না, আর এর AI ফোনে চলে। উত্তর ও এজেন্ট শুধু আপনার ভ্রমণ ও দৈনন্দিন তথ্য ব্যবহার করে (কখনো পাসপোর্ট, ফোন বা ইমেইল নয়)। বুকিং সাইট আপনার নাম, পাসপোর্ট ও ফোন পায় শুধু যখন «আমার তথ্য পূরণ করুন» চাপেন।",
  "Use my details to make answers and agents fit me": "উত্তর ও এজেন্টকে আমার মতো করতে আমার তথ্য ব্যবহার করুন",
  "Trips and hotels": "ভ্রমণ ও হোটেল",
  "Agents use these when your sentence doesn't say — e.g. a hotel watch looks for your stars by itself.": "আপনার বাক্যে না থাকলে এজেন্ট এগুলো ব্যবহার করে — যেমন হোটেলের নজর নিজেই আপনার তারকা খোঁজে।",
  "Daily life": "দৈনন্দিন জীবন",
  "So Chat's answers fit you: food, health, your car, your work.": "যাতে চ্যাটের উত্তর আপনার মানানসই হয়: খাবার, স্বাস্থ্য, আপনার গাড়ি, আপনার কাজ।",
