  "With more than one model installed: quick questions use the one already running; code, maths, reasoning and long reports move to your strongest model that runs smoothly here, and photos to one that sees. A switch takes 10–30 s.": "একাধিক মডেল ইনস্টল থাকলে: দ্রুত প্রশ্ন ইতিমধ্যে চলা মডেল ব্যবহার করে; কোড, গণিত, যুক্তি ও দীর্ঘ রিপোর্ট এখানে মসৃণভাবে চলা সবচেয়ে শক্তিশালী মডেলে যায়, আর ছবি দেখতে পারা মডেলে। বদলাতে 10–30 সেকেন্ড লাগে।",
  "The model itself never uses the network. The log lists every connection the app made or refused, host and reason only — the proof behind \\\"nothing leaves this phone\\\".": "মডেল নিজে কখনো নেটওয়ার্ক ব্যবহার করে না। লগে অ্যাপের প্রতিটি সংযোগ বা প্রত্যাখ্যান তালিকাভুক্ত, শুধু হোস্ট ও কারণ — \\\"এই ফোন থেকে কিছুই যায় না\\\"-এর প্রমাণ।",
