  "Turn these steps into a short checklist I can tick.": "এই ধাপগুলোকে টিক দেওয়ার মতো ছোট চেকলিস্ট বানাও।",
  "Give me a real-world example with numbers.": "সংখ্যাসহ একটি বাস্তব উদাহরণ দাও।",
  "Explain that simply, as if I have no background.": "সহজভাবে বোঝাও, যেন আমার কোনো পূর্বজ্ঞান নেই।",
