  "Tell me more about the first option.": "প্রথম বিকল্প নিয়ে আরও বলো।",
  "Turn the plan into a checklist.": "পরিকল্পনাকে চেকলিস্ট বানাও।",
  "Translate it back so I can check the meaning.": "অর্থ যাচাই করতে আবার অনুবাদ করে দেখাও।",
