  "the delivery date, and a penalty if late": "ডেলিভারির তারিখ, আর দেরিতে জরিমানা",
  "what happens if it is not delivered": "ডেলিভারি না হলে কী হবে",
  "the interest or fees": "সুদ বা ফি",
  "the repayment schedule": "পরিশোধের সময়সূচি",
  "what exactly will be delivered": "ঠিক কী ডেলিভারি হবে",
  "the price and when it is paid": "দাম ও কবে দেওয়া হবে",
  "the deadline": "শেষ সময়",
  "Ask for a normal deposit or a bank guarantee instead, and never sign anything blank.": "বরং সাধারণ জামানত বা ব্যাংক গ্যারান্টি চান, আর কখনো ফাঁকা কিছুতে সই করবেন না।",
  "It renews by itself — you keep paying unless you cancel in time.": "এটি নিজে রিনিউ হয় — সময়মতো বাতিল না করলে দিতেই থাকবেন।",
  "Ask for renewal only by written agreement, or put the cancel-by date in your Deadline Radar.": "শুধু লিখিত চুক্তিতে রিনিউ চান, বা বাতিলের শেষ তারিখ ডেডলাইন রাডারে রাখুন।",
  "Only one side can end it, or it can be ended without notice.": "শুধু এক পক্ষ শেষ করতে পারে, বা নোটিশ ছাড়াই শেষ হতে পারে।",
  "Ask that both sides can end it, with the same written notice (e.g. 30 days).": "চান যে দুই পক্ষই একই লিখিত নোটিশে (যেমন 30 দিন) শেষ করতে পারবে।",
  "The other side can change the terms or the price on its own.": "অন্য পক্ষ নিজে শর্ত বা দাম বদলাতে পারে।",
  "Ask that changes need both signatures, and that you can leave without a penalty if you don't accept them.": "চান যে পরিবর্তনে দুজনের সই লাগবে, আর না মানলে জরিমানা ছাড়া চলে যেতে পারবেন।",
  "A penalty or forfeit clause — check the amount and that it applies to both sides.": "জরিমানা বা বাজেয়াপ্তির ধারা — পরিমাণ যাচাই করুন আর এটি দুই পক্ষেই প্রযোজ্য কিনা।",
  "Ask for a cap (e.g. one month's value) and the same penalty for the other side.": "সীমা চান (যেমন এক মাসের মূল্য) আর অন্য পক্ষেরও একই জরিমানা।",
  "Money you pay here does not come back, even if the deal falls through.": "এখানে দেওয়া টাকা ফেরত আসে না, চুক্তি ভেঙে গেলেও।",
  "Ask that it is refunded if the other side cancels or doesn't deliver.": "চান যে অন্য পক্ষ বাতিল করলে বা ডেলিভারি না দিলে ফেরত দেবে।",
  "You carry all the risk, with no limit.": "সব ঝুঁকি আপনার, কোনো সীমা ছাড়া।",
  "Ask for a limit (e.g. the contract's value) and to exclude what you can't control.": "সীমা চান (যেমন চুক্তির মূল্য) আর যা আপনার নিয়ন্ত্রণে নেই তা বাদ দিতে।",
  "You may not work for a competitor after you leave — check how long and where.": "ছাড়ার পর হয়তো প্রতিযোগীর হয়ে কাজ করতে পারবেন না — কতদিন ও কোথায় যাচাই করুন।",
  "Ask for 6–12 months at most, one city or field, and pay for the time it applies.": "সর্বোচ্চ 6–12 মাস, একটি শহর বা ক্ষেত্র, আর সেই সময়ের জন্য টাকা চান।",
  "Everything you make — even in your own time — would belong to them.": "আপনি যা বানান — নিজের সময়েও — তাদের হয়ে যাবে।",
  "Ask to limit it to work done for them, in work time, with their tools.": "শুধু তাদের জন্য, কাজের সময়ে, তাদের সরঞ্জাম দিয়ে করা কাজে সীমিত করতে বলুন।",
  "Disputes go to arbitration or to another country's courts — this can be slow and expensive for you.": "বিরোধ সালিশে বা অন্য দেশের আদালতে যায় — আপনার জন্য ধীর ও ব্যয়বহুল হতে পারে।",
  "Ask for the courts of your own city.": "নিজের শহরের আদালত চান।",
  "You give up a right (to sue, to a refund, to object).": "আপনি একটি অধিকার ছেড়ে দেন (মামলা, ফেরত, আপত্তি)।",
  "Ask to delete the waiver.": "ছাড়ের ধারা মুছতে বলুন।",
  "Sold as it is, with no guarantee — problems found later are yours.": "যেমন আছে তেমন বিক্রি, কোনো গ্যারান্টি নেই — পরে পাওয়া সমস্যা আপনার।",
  "Inspect it first (with an expert), or ask for a written guarantee period.": "আগে পরিদর্শন করুন (বিশেষজ্ঞসহ), বা লিখিত গ্যারান্টির মেয়াদ চান।",
  "Secrecy that never ends.": "কখনো শেষ না হওয়া গোপনীয়তা।",
  "Ask for a fixed number of years (2–5 is common).": "নির্দিষ্ট বছর চান (সাধারণত 2–5)।",
  "They may take money from your salary — check when and how much.": "তারা বেতন থেকে কাটতে পারে — কবে ও কত যাচাই করুন।",
  "Ask that deductions are only for set reasons, with a written notice and a cap.": "চান যে কাটা শুধু নির্দিষ্ট কারণে, লিখিত নোটিশ ও সীমাসহ।",
  "Ask for no more than about 1–2 % a month, and a few days' grace.": "মাসে প্রায় 1–2%-এর বেশি নয়, আর কয়েক দিনের ছাড় চান।",
  "Ask for 5–10 % a year, written as a fixed schedule.": "বছরে 5–10% চান, নির্দিষ্ট সময়সূচি হিসেবে লেখা।",
  "Ask for 3 months.": "3 মাস চান।",
