  "Explain what you mean, e.g. “the price is 38,000 cash; 12,400 is the down payment”": "কী বোঝাচ্ছেন ব্যাখ্যা করুন, যেমন «দাম 38,000 নগদ; 12,400 হলো অগ্রিম»",
