  "They ask for a code sent to your phone — that is how accounts and wallets are stolen.": "আপনার ফোনে পাঠানো কোড চায় — এভাবেই অ্যাকাউন্ট ও ওয়ালেট চুরি হয়।",
  "A prize you never entered for.": "এমন পুরস্কার যাতে আপনি কখনো অংশ নেননি।",
  "Pressure to decide fast — a classic trick.": "দ্রুত সিদ্ধান্তের চাপ — পুরোনো কৌশল।",
  "They move you off the platform, where you lose buyer protection.": "প্ল্যাটফর্মের বাইরে নিয়ে যায়, যেখানে ক্রেতা সুরক্ষা হারান।",
  "Guaranteed high profit — the sign of a Ponzi / investment scam.": "নিশ্চিত উচ্চ লাভ — পঞ্জি / বিনিয়োগ প্রতারণার চিহ্ন।",
  "No warranty or returns.": "কোনো ওয়ারেন্টি বা ফেরত নেই।",
  "It says copy / replica — not the original product.": "কপি / রেপ্লিকা লেখা — আসল পণ্য নয়।",
  "No real brand is named.": "কোনো আসল ব্র্যান্ডের নাম নেই।",
  "Says 0% interest — the real cost is checked below.": "0% সুদ বলে — আসল খরচ নিচে যাচাই করা হয়েছে।",
  "A seller with no ratings.": "রেটিং ছাড়া বিক্রেতা।",
  "The installments add nothing over the cash price — a real 0%.": "কিস্তি নগদ দামের উপর কিছু যোগ করে না — আসল 0%।",
  "Can I see it and pay on delivery (cash / card on receipt)?": "আমি কি দেখে ডেলিভারিতে দিতে পারি (পেয়ে নগদ / কার্ড)?",
  "What is the exact brand and model number? Can you send a photo of the label?": "ঠিক ব্র্যান্ড ও মডেল নম্বর কী? লেবেলের ছবি পাঠাতে পারবেন?",
  "Is there an official warranty, and for how long? Invoice included?": "অফিসিয়াল ওয়ারেন্টি আছে, কতদিন? ইনভয়েস দেবেন?",
  "Can you do a better price? Others sell it for less.": "আরও ভালো দাম দিতে পারবেন? অন্যরা কম দামে বেচে।",
  "What is the total I pay, all fees included? Is there an early-payment penalty?": "সব ফি সহ মোট কত দেব? আগে শোধ করলে জরিমানা আছে?",
  "Can I take it to an independent mechanic and check the papers (license, violations)?": "স্বাধীন মেকানিককে দেখিয়ে কাগজ (লাইসেন্স, জরিমানা) যাচাই করতে পারি?",
  "Is the contract registered, and who pays the maintenance and utilities?": "চুক্তি কি নিবন্ধিত, আর রক্ষণাবেক্ষণ ও ইউটিলিটি কে দেয়?",
  "Can I get everything agreed in writing?": "সব কথা লিখিত পেতে পারি?",
  "No price was found in the offer.": "অফারে কোনো দাম পাওয়া যায়নি।",
  "The installments add up to less than the cash price — one of them was probably misread.": "কিস্তির যোগফল নগদ দামের চেয়ে কম — হয়তো একটি ভুল পড়া হয়েছে।",
  "The number of months is written but not the monthly amount.": "মাসের সংখ্যা লেখা আছে কিন্তু মাসিক পরিমাণ নেই।",
