  "Offline food pack": "অফলাইন খাবার প্যাক",
  "Over a million packaged foods from Open Food Facts — Egyptian and Arab products first. Search by name or barcode with no signal.": "Open Food Facts থেকে দশ লক্ষাধিক প্যাকেটজাত খাবার — মিশরীয় ও আরব পণ্য আগে। সিগন্যাল ছাড়াই নাম বা বারকোডে খুঁজুন।",
  "Get Egypt + most popular (~240,000, ~30 MB)": "মিশর + সবচেয়ে জনপ্রিয় নিন (~240,000, ~30 MB)",
