  "To answer any question, install an AI model in Engine. Commands (send…, remind me…, open…) work without one.": "যেকোনো প্রশ্নের উত্তরের জন্য ইঞ্জিনে একটি AI মডেল ইনস্টল করুন। কমান্ড (পাঠাও…, মনে করিও…, খোলো…) এটি ছাড়াই কাজ করে।",
