  "a she-camel in her 2nd year (bint makhāḍ)": "দ্বিতীয় বছরের উটনী (বিনতে মাখাদ)",
  "a she-camel in her 3rd year (bint labūn)": "তৃতীয় বছরের উটনী (বিনতে লাবুন)",
  "a she-camel in her 4th year (ḥiqqah)": "চতুর্থ বছরের উটনী (হিক্কা)",
