  "Close this Zakāt year? Its payments become one closed year with a certificate, and a new Zakāt year starts today.": "এই যাকাত বছর বন্ধ করবেন? এর পেমেন্টগুলো সার্টিফিকেটসহ একটি বন্ধ বছর হবে, আর আজ থেকে নতুন যাকাত বছর শুরু হবে।",
