  "You owe {a}. Scholars differ on whether a debt is taken off the wealth you pay Zakāt on. It is your choice — until you choose, nothing is taken off.": "আপনার {a} ঋণ আছে। যে সম্পদের যাকাত দেন, তা থেকে ঋণ বাদ যাবে কি না—এ নিয়ে আলেমদের মতভেদ আছে। সিদ্ধান্ত আপনার — আপনি না বেছে নেওয়া পর্যন্ত কিছুই বাদ যাবে না।",
