  "No closed year yet — when you finish paying a year's Zakāt, close it here and keep its certificate.": "এখনও কোনো বন্ধ বছর নেই — এক বছরের যাকাত দেওয়া শেষ হলে এখানে বন্ধ করুন এবং সার্টিফিকেট রাখুন।",
  "An estimate to guide you. It uses the gold nisab (85g) and 2.5% on cash, gold, silver and money owed to you — not your home, car, or work equipment. Rulings on debts and on dropping below nisab during the year differ between scholars; confirm your case with a trusted scholar.": "দিকনির্দেশনার জন্য একটি আনুমানিক হিসাব। এটি সোনার নিসাব (৮৫ গ্রাম) এবং নগদ, সোনা, রুপা ও আপনার পাওনা টাকার ওপর ২.৫% ধরে — আপনার বাড়ি, গাড়ি বা কাজের সরঞ্জামের ওপর নয়। ঋণ এবং বছরের মাঝে নিসাবের নিচে নামা নিয়ে আলেমদের মতভেদ আছে; বিশ্বস্ত আলেমের কাছে নিজের বিষয়টি নিশ্চিত করুন।",
  "Nothing yet today — tell the box what you spent or need to remember.": "আজ এখনও কিছু নেই — বক্সে বলুন কী খরচ করলেন বা কী মনে রাখতে হবে।",
  "These offers were read before Attune could read the hotel names and photos — tap Check now to get them.": "Attune হোটেলের নাম ও ছবি পড়তে পারার আগে এই অফারগুলো পড়া হয়েছিল — সেগুলো পেতে এখনই চেক করুন চাপুন।",
