  "Let Attune read your notifications to plan your day": "দিন সাজাতে Attune-কে আপনার নোটিফিকেশন পড়তে দিন",
  "On this phone only — nothing is sent anywhere.": "শুধু এই ফোনে — কিছু পাঠানো হয় না।",
  "Iftar · Maghrib {t}": "ইফতার · মাগরিব {t}",
