  "Birthdays, reminders to people, a message for later — once, or every day, week, month or year.": "জন্মদিন, মানুষকে মনে করানো, পরে পাঠানোর মেসেজ — একবার, বা প্রতিদিন, সপ্তাহে, মাসে বা বছরে।",
  "asks first": "আগে জিজ্ঞেস করে",
  "How messages are sent": "মেসেজ কীভাবে যায়",
  "Through the chat's own reply when its notification is on your phone; otherwise a notification opens the chat with the message written — one tap on Send.": "চ্যাটের নিজের উত্তর দিয়ে, যখন তার নোটিফিকেশন আপনার ফোনে থাকে; নইলে একটি নোটিফিকেশন লেখা মেসেজসহ চ্যাট খোলে — পাঠান-এ একবার চাপ।",
  "Send by itself is on (WhatsApp, phone unlocked).": "“নিজে পাঠাও” চালু আছে (WhatsApp, ফোন আনলক)।",
  "Turn on “Send by itself” (like Auto Text)": "“নিজে পাঠাও” চালু করুন (Auto Text-এর মতো)",
  "Allow SMS to be sent by itself": "SMS নিজে পাঠানোর অনুমতি দিন",
  "What “Send by itself” does": "“নিজে পাঠাও” কী করে",
  "At a message's time, Attune opens that WhatsApp chat with your message written and presses Send for you.": "মেসেজের সময় Attune সেই WhatsApp চ্যাট আপনার মেসেজ লিখে খোলে এবং আপনার হয়ে পাঠান চাপে।",
  "It uses Android's Accessibility service only for that: only in WhatsApp, only for messages you scheduled, only when the box holds your message.": "এটি Android-এর অ্যাক্সেসিবিলিটি সার্ভিস শুধু এর জন্যই ব্যবহার করে: শুধু WhatsApp-এ, শুধু আপনার নির্ধারিত মেসেজের জন্য, শুধু যখন বক্সে আপনার মেসেজ থাকে।",
  "It reads nothing else and sends nothing else. When the phone is locked it can't — you get the one-tap notification instead.": "এটি আর কিছু পড়ে না বা পাঠায় না। ফোন লক থাকলে পারে না — তখন এক-চাপের নোটিফিকেশন আসে।",
  "Open Accessibility settings": "অ্যাক্সেসিবিলিটি সেটিংস খুলুন",
  "In Settings: Accessibility → Attune → turn it on. Come back here after.": "সেটিংসে: অ্যাক্সেসিবিলিটি → Attune → চালু করুন। তারপর এখানে ফিরুন।",
  "Attune answers by itself through the chat's own reply — it needs Notification access, and works in every version.": "Attune চ্যাটের নিজের উত্তর দিয়ে নিজেই উত্তর দেয় — নোটিফিকেশন অ্যাক্সেস লাগে, সব সংস্করণে চলে।",
