  "Traffic fines, bills, licences, a crane's inspection — all in one list.": "জরিমানা, বিল, লাইসেন্স, ক্রেনের পরিদর্শন — সব এক তালিকায়।",
  "driving licence expires 20 Nov 2026": "ড্রাইভিং লাইসেন্স ২০ নভে ২০২৬ শেষ",
  "Driving licence · in 13 days": "ড্রাইভিং লাইসেন্স · ১৩ দিনে",
  "“Car licence expires 3 Feb 2027”": "«গাড়ির রেজিস্ট্রেশন ৩ ফেব্রু ২০২৭ শেষ»",
  "Told before it is due, with the papers to bring": "তারিখের আগে জানানো, কাগজসহ",
  "Each place is one page with tabs on top — Money opens on your money, with Follow-ups next to it.": "প্রতিটি জায়গা উপরে ট্যাবসহ একটি পৃষ্ঠা — টাকা আপনার টাকায় খোলে, পাশে ফলো-আপ।",
  "Attune puts it in the right place — Money, Reminders, People & plans, To-dos, Dates — and says what it did. Wrong? Tap Undo.": "Attune এটিকে ঠিক জায়গায় রাখে — টাকা, রিমাইন্ডার, মানুষ ও পরিকল্পনা, কাজ, তারিখ — আর বলে কী করেছে। ভুল? পূর্বাবস্থা চাপুন।",
  "One sentence does a lot: “Ahmed owes me 12,000, 1,000 a month” becomes 12 payments with a reminder before each one.": "একটি বাক্য অনেক কিছু করে: «আহমেদের কাছে আমার ১২,০০০, মাসে ১,০০০» প্রতিটির আগে রিমাইন্ডারসহ ১২টি কিস্তি হয়ে যায়।",
  "Type a goal with a number and a date: «عايز أوفر 60 ألف قبل يونيو», “lose 6 kg before 20 January”, a Corolla 2022 under 900,000 before 1 December. Tap Start the mission. More kinds: a spending limit («مش عايز أصرف أكتر من 3000 على الأكل الشهر ده») and a debt from Money → People («عايز أخلص دين أحمد قبل ديسمبر»).": "সংখ্যা ও তারিখসহ লক্ষ্য লিখুন: «عايز أوفر 60 ألف قبل يونيو», «২০ জানুয়ারির আগে ৬ কেজি কমানো», ১ ডিসেম্বরের আগে ৯০০,০০০-এর কমে Corolla 2022। মিশন শুরু চাপুন। আরও ধরন: খরচের সীমা («مش عايز أصرف أكتر من 3000 على الأكل الشهر ده») এবং টাকা → মানুষ থেকে একটি ঋণ («عايز أخلص دين أحمد قبل ديسمبر»)।",
  "Every time Attune opens it reads your Money and the prices your agents saw, and shows your real chance (from your own past days, thousands of possible futures) and your progress.": "Attune প্রতিবার খুললে আপনার টাকা ও এজেন্টদের দেখা দাম পড়ে, আর আপনার আসল সম্ভাবনা (আপনার নিজের দিন থেকে, হাজারো সম্ভাব্য ভবিষ্যৎ) ও অগ্রগতি দেখায়।",
  "Tools holds Writing, Files & Converter and Ask a PDF — tap one to open it.": "টুলসে আছে লেখা, ফাইল ও কনভার্টার এবং PDF-কে জিজ্ঞাসা — খুলতে একটিতে ট্যাপ করুন।",
  "Paste once, then try another action on the same text.": "একবার পেস্ট করুন, তারপর একই লেখায় অন্য কাজ চেষ্টা করুন।",
  "Save it as:": "এভাবে সংরক্ষণ করুন:",
  "Or say how — “remind me Monday at 9”, “subscription 200 every month”": "অথবা বলুন কীভাবে — «সোমবার ৯টায় মনে করিয়ে দিও», «প্রতি মাসে ২০০ সাবস্ক্রিপশন»",
  "I couldn't read that — try “reminder tomorrow at 9” or “expense 450”": "বুঝতে পারিনি — «কাল ৯টায় রিমাইন্ডার» বা «খরচ ৪৫০» চেষ্টা করুন",
  "If your money stays as it is, you will pay about {a} on {d} ({p}% of {b}).": "আপনার টাকা এমন থাকলে {d} তারিখে প্রায় {a} দেবেন ({b}-এর {p}%)।",
  "If your money stays as it is, it stays under the niṣāb — no Zakāt this year.": "আপনার টাকা এমন থাকলে নিসাবের নিচে থাকবে — এ বছর যাকাত নেই।",
  "the end of your ḥawl": "আপনার হাওলের শেষ",
  "breakfast": "নাশতা",
