  "Nothing found yet — it keeps checking.": "এখনো কিছু নেই — খোঁজা চলছে।",
  "Researching in the background — you can leave Attune; I'll tell you when it's ready": "পটভূমিতে গবেষণা চলছে — Attune ছেড়ে যেতে পারেন; তৈরি হলে জানাব",
  "Install an AI model in Engine to research": "গবেষণার জন্য ইঞ্জিনে একটি AI মডেল ইনস্টল করুন",
