  "Which one do you mean? {list}": "কোনটি বোঝাচ্ছেন? {list}",
  "{w} is a plan with a total of {t} — change it in People & plans so the total stays right.": "{w} মোট {t}-এর একটি পরিকল্পনা — মোট ঠিক রাখতে মানুষ ও পরিকল্পনা-তে বদলান।",
  "{w} is already {a} — nothing changed.": "{w} আগে থেকেই {a} — কিছু বদলায়নি।",
  "Done — {w} stopped from today. What was paid before stays in Money.": "হয়ে গেছে — {w} আজ থেকে বন্ধ। আগে যা দেওয়া হয়েছে তা টাকায় থাকবে।",
  "Done — {w} is now {a} from today (was {b}).": "হয়ে গেছে — {w} আজ থেকে {a} (আগে {b})।",
