  "I couldn't read classes in this photo. An Arabic or handwritten timetable needs a model marked 📷 in Engine.": "এই ছবিতে ক্লাস পড়তে পারিনি। আরবি বা হাতে লেখা রুটিনের জন্য ইঞ্জিনে 📷 চিহ্নিত মডেল লাগবে।",
  "{n} classes saved — a reminder {m} min before each": "{n}টি ক্লাস সেভ — প্রতিটির {m} মিনিট আগে রিমাইন্ডার",
